  ('db6b5671-712a-5bd2-9013-f19a390e7d16', 'TF2570-000001', 1, 'c9f28b26-6323-548a-8053-ac5c173be1e3', 1, 'NEW', false, NULL, 'draft', false, 'primary', 'ป.5', 'ป.6', 'P6', NULL, NULL, NULL, NULL, NULL, true, 'student001@example.com', 'm6', NULL, NULL, NULL, NULL, NULL, 30, false, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, '53 หมู่ 4 ตำบลในเวียง อำเภอเมืองแพร่ จังหวัดแพร่ 54000', '53 หมู่ 4 ตำบลในเวียง อำเภอเมืองแพร่ จังหวัดแพร่ 54000', 'อาศัยอยู่กับพ่อแม่ ผู้ปกครองมีรายได้ไม่แน่นอน ต้องดูแลสมาชิกหลายคน', 'มีพี่น้อง 1 คน แม่เป็นผู้ออกค่าใช้จ่ายหลัก', 'ซ้อนรถจักรยานยนต์ผู้ปกครองมาโรงเรียน ใช้เวลาประมาณ 20 นาที ได้เงินไปโรงเรียนวันละ 50 บาท', 'บ้านไม้สองชั้นที่ทรุดโทรม พื้นผุบางส่วน', 'ค่าใช้จ่ายในบ้านประมาณ 4,000 บาทต่อเดือน และมีหนี้นอกระบบ', 'อยากเรียนต่อพยาบาล', 'ต้องการแบ่งเบาภาระค่าใช้จ่ายของครอบครัว และใช้เป็นค่าอุปกรณ์การเรียนและค่าเดินทาง', NULL, false, NULL, NULL, NULL, false),
